-- 관악산 주변 편의시설 (서울 공중화장실 보강, 경기 공중화장실, 서울·경기 주차장)

-- 출처: 서울시 공중화장실 위치정보(OA-22586), 행정안전부 공중화장실정보, 전국주차장정보표준데이터

-- 대상 좌표계: EPSG:5179

BEGIN;

-- 이 파일보다 01~04 시드를 먼저 실행해야 한다 (service_area 로 범위를 거른다).
-- 서울 공중화장실: 01 시드는 당시 개발용 버퍼(116200201 등산로) 주변 30건만 넣었다.
--   02 시드로 넓어진 서비스 영역의 나머지 서울 화장실을 01 과 같은 파일(SHA-256 동일)·같은 데이터셋에 추가한다.
--   이미 있는 30건은 (dataset_id, src_fac_id) 충돌로 건너뛴다.
-- 경기 공중화장실(과천·안양)과 서울·경기 주차장은 새 데이터셋으로 넣는다.
-- 범위: 사용 중인 관악산 service_area 에서 500m 이내.
--   01 시드의 서울 화장실 30건이 당시 개발용 등산로 버퍼에서 500m 이내에 있어 같은 수준으로 맞췄다.
-- dataset_id 는 dataset_nm 으로 조회하며, 다시 실행해도 같은 행이 중복되지 않는다.
--
-- 메타데이터 확인 상태:
--   * 공중화장실: 행정안전부 지역별 파일(경기 과천시·안양시). 2025년 2월부터 원천 좌표 제공이 중단되어
--     주소를 브이월드 지오코더 API 2.0 으로 EPSG:4326 좌표로 변환했다 (loc_basis_cd = GEOCODE).
--     도로명주소로 먼저 찾고 실패하면 지번주소로 찾았다. 둘 다 실패한 2건(상하수도 사업소)은 넣지 않았다.
--     안양시는 관악산에 닿는 관양·석수·비산동과 관악대로 주소만 변환했다.
--   * 주차장: 원천 위도·경도(EPSG:4326)를 그대로 쓴다 (loc_basis_cd = SOURCE_COORD).
--     주차장관리번호가 전국에서 고유하지 않아 src_fac_id 는 '제공기관코드:주차장관리번호' 이다.
--   * 원천 행마다 데이터기준일자가 달라 base_de 는 NULL 이며 행별 값은 src_attr_json 에 보존한다.
--   * collect_de 는 파일을 내려받은 날(2026-11-01)이다.
--   * file_hash 는 원본 파일 해시가 아니라 데이터셋별 INSERT 데이터의 SHA-256 이며 data_ver 에는 그 앞부분을 사용했다.
--   * 같은 시설이 여러 기관 자료에 중복될 수 있으나 검수 전이므로 dup_of_facility_id 는 채우지 않았다.
INSERT INTO public.source_dataset (
    dataset_nm, origin_cd, data_type_cd, provider_nm, source_url, base_de, collect_de,
    src_crs_cd, file_nm, file_hash, license_nm, data_ver, dataset_desc
)
SELECT seed.*
FROM (
    VALUES
    ('mois:toilet:15012892:gyeonggi', 'PUBLIC', 'FACILITY', '행정안전부', 'https://www.data.go.kr/data/15012892/standard.do', NULL::date, DATE '2026-11-01', 'EPSG:4326', '공중화장실정보_경기과천시.csv, 공중화장실정보_경기안양시.csv', 'f1f796a3a444b60d5f73abfc201797dfa445ff0eb87880b4292ebc110d8875d2', NULL, 'sha256:f1f796a3a444b60d', '행정안전부 공중화장실정보 경기 과천시·안양시 지역별 파일. 원천 좌표 제공 중단으로 주소를 브이월드 지오코더 API 2.0 으로 EPSG:4326 변환(loc_basis_cd=GEOCODE); file_hash/data_ver 는 이 시드의 INSERT payload SHA-256 기반(원본 파일 해시 아님).'),
    ('molit:parking:15012896', 'PUBLIC', 'FACILITY', '국토교통부', 'https://www.data.go.kr/data/15012896/standard.do', NULL::date, DATE '2026-11-01', 'EPSG:4326', '전국주차장정보표준데이터.csv', '1be3809646202d03f5c14a2f63ec8e279912fdbda084f177589d5109817732c3', NULL, 'sha256:1be3809646202d03', '전국주차장정보표준데이터(지방자치단체 등록 자료 취합) 그리드 CSV. 원천 위도·경도 사용; src_fac_id=제공기관코드:주차장관리번호; file_hash/data_ver 는 이 시드의 INSERT payload SHA-256 기반(원본 파일 해시 아님).')
) AS seed (
    dataset_nm, origin_cd, data_type_cd, provider_nm, source_url, base_de, collect_de,
    src_crs_cd, file_nm, file_hash, license_nm, data_ver, dataset_desc
)
WHERE NOT EXISTS (
    SELECT 1
    FROM public.source_dataset AS existing
    WHERE existing.dataset_nm = seed.dataset_nm
);

