WHERE EXISTS (
    SELECT 1
    FROM public.service_area AS area
    WHERE area.mountain_id = 2
      AND area.use_yn = 'Y'
      AND ST_DWithin(seed.geom, area.geom, 500)
)
ON CONFLICT (dataset_id, src_fac_id)
DO NOTHING;

-- 서비스 영역이 없거나 데이터셋 연결이 틀려 한 건도 들어가지 않았으면 실패시킨다.
DO $$
DECLARE
    toilet_cnt bigint;
    parking_cnt bigint;
BEGIN
    SELECT count(*) FILTER (WHERE dataset.dataset_nm = 'mois:toilet:15012892:gyeonggi'),
           count(*) FILTER (WHERE dataset.dataset_nm = 'molit:parking:15012896')
    INTO toilet_cnt, parking_cnt
    FROM public.facility AS facility
    JOIN public.source_dataset AS dataset ON dataset.dataset_id = facility.dataset_id;
    IF toilet_cnt = 0 OR parking_cnt = 0 THEN
        RAISE EXCEPTION '편의시설 적재 실패: 화장실 %, 주차장 %', toilet_cnt, parking_cnt;
    END IF;
END
$$;

COMMIT;
